	/* ---- Audio ---- */
	AudioServer::PlaybackType playback_type;

	/* ---- Blending processor ---- */
	LocalVector<AnimationInstance> animation_instances;
	uint64_t animation_instance_weight_pass_counter = 0;
	AHashMap<NodePath, int> track_map;
