	GodotStep2D* stepper = nullptr;
	HashSet<GodotSpace2D*> active_spaces;

	mutable RID_PtrOwner<GodotShape2D, true> shape_owner;
	mutable RID_PtrOwner<GodotSpace2D, true> space_owner;
